const item = $input.first().json;

// Parse AI response
let aiData = {};
try {
  const aiResponse = JSON.parse(item.choices[0].message.content);
  aiData = {
    ai_score: aiResponse.ai_score || 7,
    recommended: aiResponse.recommended || 'YES',
    summary: aiResponse.summary || 'Надежный поставщик',
    pros: aiResponse.pros || 'Хороший рейтинг',
    risks: aiResponse.risks || 'Стандартные риски'
  };
} catch (e) {
  // Fallback if AI parsing fails
  aiData = {
    ai_score: 7,
    recommended: 'YES',
    summary: 'Анализ в процессе',
    pros: 'Проверенный поставщик',
    risks: 'Требуется дополнительная проверка'
  };
}

return {
  json: {
    ...item,
    ...aiData,
    timestamp: new Date().toISOString()
  }
};

// Aggregate all suppliers into one table message
const items = $input.all();
const category = items[0].json.product_category;
const chatId = items[0].json.chat_id;

// Create table header
let message = `📊 *Найдено ${items.length} поставщиков: ${category}*\n\n`;

// Add each supplier as a row
items.forEach((item, index) => {
  const d = item.json;
  const num = index + 1;
  const star = d.recommended === 'YES' ? '⭐️' : '📍';

  message += `${star} *${num}. ${d.company_name}*\n`;
  message += `┣ 🎯 AI: ${d.ai_score}/10 | ⭐️ ${d.rating}/5\n`;
  message += `┣ 📦 MOQ: ${d.moq} | 💰 ${d.price}\n`;
  message += `┣ 📍 ${d.location}\n`;
  message += `┣ 📧 ${d.contact_email}\n`;
  message += `┣ 🌐 ${d.company_url}\n`;
  message += `┣ ✅ ${d.pros}\n`;
  message += `┗ ⚠️ ${d.risks}\n\n`;
});

message += `\n_Все данные сохранены в Google Sheets_ 📝`;

return {
  json: {
    chat_id: chatId,
    message: message
  }
};
